// Java SDK v2 — assume cross-account role
import software.amazon.awssdk.services.sts.StsClient;
import software.amazon.awssdk.services.sts.model.AssumeRoleResponse;
import software.amazon.awssdk.auth.credentials.AwsSessionCredentials;
import software.amazon.awssdk.auth.credentials.StaticCredentialsProvider;

StsClient stsClient = StsClient.create();

AssumeRoleResponse response = stsClient.assumeRole(r -> r
    .roleArn("arn:aws:iam::999988887777:role/CrossAccountRole")
    .roleSessionName("my-session")
    .externalId("UniqueExternalId123")
    .durationSeconds(3600)
);

AwsSessionCredentials tempCreds = AwsSessionCredentials.create(
    response.credentials().accessKeyId(),
    response.credentials().secretAccessKey(),
    response.credentials().sessionToken()
);

S3Client s3InOtherAccount = S3Client.builder()
    .credentialsProvider(StaticCredentialsProvider.create(tempCreds))
    .region(Region.US_EAST_1)
    .build();

// STS GetCallerIdentity — verify current credentials
StsClient stsClient = StsClient.create();
GetCallerIdentityResponse identity = stsClient.getCallerIdentity();
System.out.println("Account: " + identity.account());
System.out.println("User: " + identity.arn());

// STS AssumeRoleWithWebIdentity (simplified — use Cognito in production)
String webIdentityToken = getTokenFromCognito(); // your app logic

AssumeRoleWithWebIdentityResponse response = stsClient.assumeRoleWithWebIdentity(r -> r
    .roleArn("arn:aws:iam::123456789:role/MobileAppRole")
    .roleSessionName("mobile-user-" + userId)
    .webIdentityToken(webIdentityToken)
    .durationSeconds(3600)
);

// Temporary credential structure:
// response.credentials().accessKeyId()     → "ASIA..."
// response.credentials().secretAccessKey() → temporary secret
// response.credentials().sessionToken()    → MUST be included in all API calls
// response.credentials().expiration()      → when they expire

// EXAM GOTCHA:
// STS temporary credentials from AssumeRole start with "ASIA"
// Permanent IAM user access keys start with "AKIA"
// If you see "ASIA" in a credentials leak, those credentials expire automatically

// EC2 Purchasing Options — Cost Comparison (us-east-1, m5.xlarge)
//
// On-Demand:          $0.192/hr   → no commitment, pay per second
// Reserved (1yr, No Upfront): $0.118/hr  → 39% savings
// Reserved (1yr, All Upfront): $0.099/hr → 48% savings
// Reserved (3yr, All Upfront): $0.062/hr → 68% savings
// Spot (approximate): $0.050/hr  → ~74% savings, can be interrupted
// Savings Plans:      ~$0.118/hr → flexible, like RI but better
//
// EXAM DECISION TREE:
// Question: "Cheapest for 24/7 production DB?"
// → Reserved Instance (1yr or 3yr, Standard)
//
// Question: "Cheapest for nightly batch job, 4 hours?"
// → Spot Instance with graceful interruption handling
//
// Question: "Need to run legacy software with per-socket licensing?"
// → Dedicated Host
//
// Question: "Development server used 9am-5pm on weekdays?"
// → On-Demand OR Scheduled Reserved Instance
//
// Question: "Unpredictable microservice, need flexibility?"
// → Compute Savings Plan (applies to Lambda/Fargate too)

# Request a Spot Instance
aws ec2 request-spot-instances \
  --spot-price "0.05" \
  --instance-count 1 \
  --type "one-time" \
  --launch-specification file://spot-spec.json

# Create and attach an EBS volume
aws ec2 create-volume \
  --availability-zone us-east-1a \
  --volume-type gp3 \
  --size 100 \
  --iops 3000 \
  --throughput 125 \
  --encrypted \
  --kms-key-id arn:aws:kms:us-east-1:123456789:key/mrk-abc123

# Attach volume to instance
aws ec2 attach-volume \
  --volume-id vol-0123456789abcdef0 \
  --instance-id i-0123456789abcdef0 \
  --device /dev/sdf

# Create snapshot of a volume
aws ec2 create-snapshot \
  --volume-id vol-0123456789abcdef0 \
  --description "Nightly backup $(date +%Y-%m-%d)"

// EBS Volume Type Decision Guide:
// gp3 → default choice for most workloads (boot volumes, apps, dev)
// io2 → high-performance databases (Oracle, SQL Server, Cassandra)
// st1 → streaming/big data (Kafka, Hadoop, log aggregation)
// sc1 → cold backups, rarely accessed archival data
//
// EXAM GOTCHA: gp3 IOPS are NOT tied to volume size (unlike gp2)
// gp2: IOPS = volume_size_GB * 3 (min 100, max 16000)
// gp3: always starts at 3000 IOPS regardless of size

# Create a security group
aws ec2 create-security-group \
  --group-name MyWebSG \
  --description "Web server security group" \
  --vpc-id vpc-0123456789abcdef0

# Add inbound rules
aws ec2 authorize-security-group-ingress \
  --group-id sg-0123456789abcdef0 \
  --protocol tcp --port 443 --cidr 0.0.0.0/0  # HTTPS from internet

aws ec2 authorize-security-group-ingress \
  --group-id sg-0123456789abcdef0 \
  --protocol tcp --port 8080 \
  --source-group sg-alb-security-group-id  # Only from ALB SG

// Security Groups vs NACLs — Exam Cheat Sheet:
//
// Security Group:
//   Level: Instance (ENI)
//   Stateful: YES (return traffic auto-allowed)
//   Rules: ALLOW only
//   Evaluation: All rules checked together
//   Default (new SG): Deny all inbound, allow all outbound
//
// NACL:
//   Level: Subnet
//   Stateful: NO (must allow both directions explicitly)
//   Rules: ALLOW and DENY
//   Evaluation: Rules evaluated in order (lowest number first)
//   Default NACL: Allow all inbound and outbound
//   Custom NACL: Deny all until you add rules
//
// KEY EXAM TRAP: Need to BLOCK a specific IP? → Use NACL (Deny rule)
// You CANNOT add a Deny rule to a Security Group!

// Java SDK v2 — S3 basic operations
import software.amazon.awssdk.core.sync.RequestBody;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.*;

S3Client s3 = S3Client.builder().region(Region.US_EAST_1).build();

// Create a bucket
s3.createBucket(b -> b.bucket("my-unique-bucket-name-2024"));

// Upload an object
s3.putObject(
    PutObjectRequest.builder()
        .bucket("my-bucket")
        .key("images/profile/user-123.jpg")
        .contentType("image/jpeg")
        .build(),
    RequestBody.fromFile(Path.of("/local/path/photo.jpg"))
);

// Download an object
ResponseBytes<GetObjectResponse> objectBytes = s3.getObjectAsBytes(
    GetObjectRequest.builder()
        .bucket("my-bucket")
        .key("images/profile/user-123.jpg")
        .build()
);
byte[] data = objectBytes.asByteArray();

// Multipart upload for large files
CreateMultipartUploadResponse initResponse = s3.createMultipartUpload(r -> r
    .bucket("my-bucket")
    .key("large-file.zip")
);
String uploadId = initResponse.uploadId();
// ... upload parts, then complete:
s3.completeMultipartUpload(r -> r
    .bucket("my-bucket")
    .key("large-file.zip")
    .uploadId(uploadId)
    .multipartUpload(CompletedMultipartUpload.builder()
        .parts(completedParts) // list of CompletedPart
        .build())
);

// S3 Storage Class Cost Tiers (us-east-1, approximate):
//
// Standard:           $0.023/GB/month  | No retrieval fee | 3+ AZs
// Intelligent-Tiering:$0.023/GB/month  | No retrieval fee | 3+ AZs
// Standard-IA:        $0.0125/GB/month | $0.01/GB retrieval | 3+ AZs
// One Zone-IA:        $0.01/GB/month   | $0.01/GB retrieval | 1 AZ
// Glacier Instant:    $0.004/GB/month  | $0.03/GB retrieval | 3+ AZs
// Glacier Flexible:   $0.0036/GB/month | $0.01-0.03/GB     | 3+ AZs
// Deep Archive:       $0.00099/GB/month| $0.0025/GB retrieval| 3+ AZs

