// Java SDK v2 — upload with SSE-KMS + generate presigned URL
import software.amazon.awssdk.services.s3.presigner.S3Presigner;
import software.amazon.awssdk.services.s3.presigner.model.PresignedGetObjectRequest;
import software.amazon.awssdk.services.s3.model.ServerSideEncryption;

S3Client s3 = S3Client.builder().region(Region.US_EAST_1).build();

// Upload with SSE-KMS encryption
PutObjectRequest putRequest = PutObjectRequest.builder()
    .bucket("secure-bucket")
    .key("sensitive/document.pdf")
    .serverSideEncryption(ServerSideEncryption.AWS_KMS)
    .ssekmsKeyId("arn:aws:kms:us-east-1:123456789:key/mrk-abc123")
    .build();

s3.putObject(putRequest, RequestBody.fromFile(filePath));

// Generate presigned URL (valid for 1 hour)
S3Presigner presigner = S3Presigner.builder()
    .region(Region.US_EAST_1)
    .build();

PresignedGetObjectRequest presignedRequest = presigner.presignGetObject(r -> r
    .signatureDuration(Duration.ofHours(1))
    .getObjectRequest(GetObjectRequest.builder()
        .bucket("secure-bucket")
        .key("sensitive/document.pdf")
        .build())
);

String presignedUrl = presignedRequest.url().toString();
// Share this URL — it works for anyone for 1 hour, then expires
presigner.close();

// Bucket policy example — deny non-HTTPS access
// {
//   "Statement": [{
//     "Effect": "Deny",
//     "Principal": "*",
//     "Action": "s3:*",
//     "Resource": ["arn:aws:s3:::my-bucket/*"],
