//   }]
// }

// Enable versioning on a bucket
s3.putBucketVersioning(r -> r
    .bucket("my-versioned-bucket")
    .versioningConfiguration(VersioningConfiguration.builder()
        .status(BucketVersioningStatus.ENABLED)
        .build())
);

// Get a specific version of an object
s3.getObject(r -> r
    .bucket("my-versioned-bucket")
    .key("config.json")
    .versionId("abc123VersionId")
    .build(), Path.of("/tmp/old-config.json"));

// Configure S3 Event Notification → SQS
aws s3api put-bucket-notification-configuration \
  --bucket my-upload-bucket \
  --notification-configuration '{
    "QueueConfigurations": [{
      "QueueArn": "arn:aws:sqs:us-east-1:123456789:image-processing-queue",
      "Events": ["s3:ObjectCreated:*"],
      "Filter": {
        "Key": {
          "FilterRules": [{"Name": "prefix", "Value": "uploads/"},
                          {"Name": "suffix", "Value": ".jpg"}]
        }
      }
    }]
  }'

// Enable Object Lock (must be done at bucket creation)
aws s3api create-bucket \
  --bucket compliance-archive \
  --object-lock-enabled-for-bucket

// Set default retention — 7 years, Compliance mode
aws s3api put-object-lock-configuration \
  --bucket compliance-archive \
  --object-lock-configuration '{
    "ObjectLockEnabled": "Enabled",
    "Rule": {
      "DefaultRetention": {"Mode": "COMPLIANCE", "Years": 7}
    }
  }'

# Enable Transfer Acceleration for a bucket
aws s3api put-bucket-accelerate-configuration \
  --bucket my-global-uploads \
  --accelerate-configuration Status=Enabled

# Use the accelerate endpoint in SDK
S3Client s3Accelerated = S3Client.builder()
    .region(Region.US_EAST_1)
    .serviceConfiguration(S3Configuration.builder()
        .accelerateModeEnabled(true)
        .build())
    .build();

// Multipart upload with parallel threads (high performance)
import software.amazon.awssdk.transfer.s3.S3TransferManager;
import software.amazon.awssdk.transfer.s3.model.UploadFileRequest;

S3TransferManager transferManager = S3TransferManager.create();

FileUpload upload = transferManager.uploadFile(UploadFileRequest.builder()
    .putObjectRequest(r -> r
        .bucket("my-bucket")
        .key("large-dataset.csv")
    )
    .source(Path.of("/data/large-dataset.csv"))
    .build());

upload.completionFuture().join(); // blocks until done
transferManager.close();

// S3 Cost Optimization Tips:
// 1. Use S3 Intelligent-Tiering for uncertain access patterns
// 2. Set lifecycle policies to delete incomplete multipart uploads
aws s3api put-bucket-lifecycle-configuration \
  --bucket my-bucket \
  --lifecycle-configuration '{
    "Rules": [{"ID": "CleanupIncompleteMultipart",
               "Status": "Enabled",
               "AbortIncompleteMultipartUpload": {"DaysAfterInitiation": 7}}]
  }'

// Lambda billing calculation:
// Memory: 512 MB
// Duration: 500ms per invocation
// Invocations: 10 million/month
//
// Compute cost = invocations * duration_seconds * memory_GB * $0.0000166667
//              = 10,000,000 * 0.5 * 0.5 * $0.0000166667
//              = $41.67/month
// Request cost = 10,000,000 / 1,000,000 * $0.20 = $2.00/month
// Free tier   = first 1M requests + 400,000 GB-seconds FREE
// Total after free tier: ~$43/month
//
// Compare to EC2 t3.micro On-Demand: $0.0104/hr = $7.49/month
// (but t3.micro can only handle ~50-100 req/s)

// Lambda resource limits quick reference:
// ┌─────────────────────┬──────────────────┐
// │ Resource            │ Limit            │
// ├─────────────────────┼──────────────────┤
// │ Timeout             │ 15 minutes       │
// │ Memory              │ 128 MB - 10 GB   │
// │ /tmp storage        │ 512 MB - 10 GB   │
// │ Deployment (zip)    │ 50 MB direct     │
// │ Deployment (unzip)  │ 250 MB           │
// │ Container image     │ 10 GB            │
// │ Default concurrency │ 1,000 per region │
// │ Environment vars    │ 4 KB total       │
// └─────────────────────┴──────────────────┘

// Lambda trigger comparison:
//
// SYNCHRONOUS (caller waits for response):
//   API Gateway → Lambda → response back to client
//   ALB         → Lambda → response back to client
//   SDK.invoke() with InvocationType=RequestResponse
//
// ASYNCHRONOUS (fire and forget):
//   S3 Event → Lambda (auto-retry x2, then DLQ)
//   SNS      → Lambda (auto-retry x2, then DLQ)
//   EventBridge → Lambda (auto-retry x2, then DLQ)
//
// POLLING (event source mapping):
//   SQS → Lambda (polls queue, batch processing)
//   DynamoDB Streams → Lambda (reads stream shard by shard)
//   Kinesis → Lambda (reads stream shard by shard)

// Configure DLQ for async Lambda failures
aws lambda update-function-event-invoke-config \
  --function-name MyFunction \
  --maximum-retry-attempts 2 \
  --maximum-event-age-in-seconds 3600 \
  --destination-config '{
    "OnFailure": {
      "Destination": "arn:aws:sqs:us-east-1:123456789:my-dlq"
    },
    "OnSuccess": {
      "Destination": "arn:aws:sqs:us-east-1:123456789:success-queue"
    }
  }'

// SQS Event Source Mapping with bisect-on-error
aws lambda create-event-source-mapping \
  --function-name MyProcessor \
  --event-source-arn arn:aws:sqs:us-east-1:123456789:my-queue \
  --batch-size 10 \
  --maximum-batching-window-in-seconds 5 \
  --bisect-batch-on-function-error true \
  --destination-config '{"OnFailure":{"Destination":"arn:aws:sqs:...:dlq"}}'

// Enable SnapStart on a Lambda function version
aws lambda create-function \
  --function-name MyJavaApi \
  --runtime java21 \
  --snap-start ApplyOn=PublishedVersions \
  --handler com.example.ApiHandler::handleRequest \
  --role arn:aws:iam::123456789:role/LambdaExecutionRole \
  --code S3Bucket=deploy-bucket,S3Key=api-1.0.jar

# Publish a version (required for SnapStart to take effect)
aws lambda publish-version --function-name MyJavaApi

# Configure Provisioned Concurrency on an alias
aws lambda create-alias \
  --function-name MyJavaApi \
  --name prod \
  --function-version 5

aws lambda put-provisioned-concurrency-config \
  --function-name MyJavaApi \
  --qualifier prod \
  --provisioned-concurrent-executions 50

// AfterRestore hook for SnapStart (re-open connections after restore)
import com.amazonaws.services.lambda.runtime.events.SnapStartEvent;

@SnapStart // Spring annotation for SnapStart compatibility
public class ApiHandler implements RequestHandler<APIGatewayProxyRequestEvent, APIGatewayProxyResponseEvent> {
    private static final DataSource dataSource;

    static {
        // This runs at snapshot time
        dataSource = buildDataSource();
    }

    // AfterRestore: called after snapshot is restored (re-establish connections)
    @AfterRestore
    public void afterRestore(SnapStartEvent event) {
        // Verify/re-establish DB connection pool
        dataSource.getConnection().close(); // ping
    }

    @Override
    public APIGatewayProxyResponseEvent handleRequest(
            APIGatewayProxyRequestEvent input, Context context) {
        // Your handler logic here
        return new APIGatewayProxyResponseEvent()
            .withStatusCode(200)
            .withBody("{\"status\": \"ok\"}");
    }
}

// Java Lambda best practice structure
import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.amazonaws.services.lambda.runtime.events.APIGatewayProxyRequestEvent;
import com.amazonaws.services.lambda.runtime.events.APIGatewayProxyResponseEvent;
import software.amazon.awssdk.services.dynamodb.DynamoDbClient;
import software.amazon.awssdk.services.s3.S3Client;
import com.fasterxml.jackson.databind.ObjectMapper;

public class OptimizedHandler implements
    RequestHandler<APIGatewayProxyRequestEvent, APIGatewayProxyResponseEvent> {

    // Initialized ONCE during cold start, reused across warm invocations
    // These are thread-safe and SDK clients internally manage connection pools
    private static final DynamoDbClient dynamoDb = DynamoDbClient.builder()
        .region(Region.US_EAST_1)
        .build();
    private static final S3Client s3 = S3Client.builder()
        .region(Region.US_EAST_1)
        .build();
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static final String TABLE_NAME = System.getenv("TABLE_NAME");

    @Override
    public APIGatewayProxyResponseEvent handleRequest(
            APIGatewayProxyRequestEvent event, Context context) {

        // Log whether this is a cold start (useful for monitoring)
        context.getLogger().log("RequestId: " + context.getAwsRequestId());

        try {
            // Your business logic here
            String body = event.getBody();
            // ... process request
            return new APIGatewayProxyResponseEvent()
                .withStatusCode(200)
                .withHeaders(Map.of("Content-Type", "application/json"))
                .withBody("{\"result\": \"success\"}");
        } catch (Exception e) {
            context.getLogger().log("Error: " + e.getMessage());
            return new APIGatewayProxyResponseEvent().withStatusCode(500);
        }
    }
}

// DynamoDB table design examples:
//
// Simple PK (Partition Key only):
// Table: Users
// PK: userId (String) — must be unique
// Items: {userId: "u-123", name: "Alice", email: "alice@example.com"}
//
// Composite PK (Partition Key + Sort Key):
// Table: Orders
// PK: customerId (String)
// SK: orderId (String)
// Allows: Get all orders for a customer (Query on PK)
//         Get specific order (Get on PK + SK)
//         Get orders from 2024 (Query with SK begins_with "2024-")
//
// Single-Table Design pattern (advanced, exam-aware):
// One table for all entities using PK/SK convention:
// PK: "USER#u-123"   SK: "PROFILE"          → user profile
// PK: "USER#u-123"   SK: "ORDER#o-456"      → user's order
// PK: "USER#u-123"   SK: "ORDER#o-789"      → user's order
// PK: "PRODUCT#p-001" SK: "METADATA"        → product info

// Create table via CLI
aws dynamodb create-table \
  --table-name Orders \
  --attribute-definitions \
      AttributeName=customerId,AttributeType=S \
      AttributeName=orderId,AttributeType=S \
  --key-schema \
      AttributeName=customerId,KeyType=HASH \
      AttributeName=orderId,KeyType=RANGE \
  --billing-mode PAY_PER_REQUEST

// RCU/WCU Calculation Examples:
//
// Item size: 3.5 KB
// Strongly consistent read: ceil(3.5/4) = 1 RCU
// Eventually consistent read: ceil(3.5/4) / 2 = 0.5 RCU
// Transactional read: ceil(3.5/4) * 2 = 2 RCU
//
// Item size: 5 KB
// Write: ceil(5/1) = 5 WCU
// Transactional write: 5 * 2 = 10 WCU
//
// Provisioning calculation:
// Expected: 1000 reads/sec of 2KB items (eventually consistent)
// RCU needed: 1000 * ceil(2/4) * 0.5 = 1000 * 1 * 0.5 = 500 RCU

// Java SDK v2 — Configure DynamoDB client with retry
DynamoDbClient dynamoDb = DynamoDbClient.builder()
    .region(Region.US_EAST_1)
    .overrideConfiguration(ClientOverrideConfiguration.builder()
        .retryPolicy(RetryPolicy.builder()
            .numRetries(5)
            .build())
        .build())
    .build();

// Update table to On-Demand mode
