// Java SDK v2 — DynamoDB operations
import software.amazon.awssdk.services.dynamodb.DynamoDbClient;
import software.amazon.awssdk.services.dynamodb.model.*;

DynamoDbClient dynamo = DynamoDbClient.create();

// PutItem with conditional write (optimistic locking)
try {
    dynamo.putItem(PutItemRequest.builder()
        .tableName("Orders")
        .item(Map.of(
            "customerId", AttributeValue.fromS("u-123"),
            "orderId", AttributeValue.fromS("o-456"),
            "status", AttributeValue.fromS("PENDING"),
            "version", AttributeValue.fromN("1"),
            "totalAmount", AttributeValue.fromN("99.99")
        ))
        .conditionExpression("attribute_not_exists(orderId)")
        .build());
} catch (ConditionalCheckFailedException e) {
    // Order already exists — handle duplicate
}

// UpdateItem with version check (optimistic locking)
dynamo.updateItem(UpdateItemRequest.builder()
    .tableName("Orders")
    .key(Map.of(
        "customerId", AttributeValue.fromS("u-123"),
        "orderId", AttributeValue.fromS("o-456")
    ))
    .updateExpression("SET #s = :newStatus, version = version + :one")
    .conditionExpression("version = :currentVersion")
    .expressionAttributeNames(Map.of("#s", "status"))
    .expressionAttributeValues(Map.of(
        ":newStatus", AttributeValue.fromS("SHIPPED"),
        ":one", AttributeValue.fromN("1"),
        ":currentVersion", AttributeValue.fromN("1")
    ))
    .build());

// Paginated query
String lastKey = null;
do {
    QueryRequest.Builder reqBuilder = QueryRequest.builder()
        .tableName("Orders")
        .keyConditionExpression("customerId = :cid")
        .expressionAttributeValues(Map.of(":cid", AttributeValue.fromS("u-123")));
    if (lastKey != null)
        reqBuilder.exclusiveStartKey(Map.of("customerId",
            AttributeValue.fromS("u-123"), "orderId",
            AttributeValue.fromS(lastKey)));
    QueryResponse resp = dynamo.query(reqBuilder.build());
    // process resp.items()
    lastKey = resp.hasLastEvaluatedKey() ? resp.lastEvaluatedKey().get("orderId").s() : null;
} while (lastKey != null);

