// Cache-Aside pattern
public Product getProduct(String productId) {
    String cacheKey = "product:" + productId;

    try (var jedis = jedisPool.getResource()) {
        // 1. Check cache
        String cached = jedis.get(cacheKey);
        if (cached != null) {
            return objectMapper.readValue(cached, Product.class);
        }

        // 2. Cache miss — fetch from database
        Product product = productRepository.findById(productId);

        // 3. Store in cache with TTL (5 minutes)
        jedis.setex(cacheKey, 300, objectMapper.writeValueAsString(product));

        return product;
    }
}

// Session storage in Redis
public void saveSession(String sessionId, UserSession session) {
    try (var jedis = jedisPool.getResource()) {
        // Store session as hash, expire in 30 minutes
        jedis.hmset("session:" + sessionId, Map.of(
            "userId", session.getUserId(),
            "role", session.getRole()
        ));
        jedis.expire("session:" + sessionId, 1800);
    }
}

