// Java SDK v2 — Send SQS message with attributes
import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;

SqsClient sqs = SqsClient.builder().region(Region.US_EAST_1).build();
String queueUrl = "https://sqs.us-east-1.amazonaws.com/123456789/my-queue";

// Send message with attributes
SendMessageResponse sendResponse = sqs.sendMessage(r -> r
    .queueUrl(queueUrl)
    .messageBody("{\"orderId\": \"o-123\", \"amount\": 99.99}")
    .messageAttributes(Map.of(
        "eventType", MessageAttributeValue.builder()
            .stringValue("ORDER_CREATED").dataType("String").build(),
        "customerId", MessageAttributeValue.builder()
            .stringValue("u-456").dataType("String").build()
    ))
    .delaySeconds(0)
);
System.out.println("Sent: " + sendResponse.messageId());

// Receive with long polling (waits up to 20s for messages)
ReceiveMessageResponse receiveResponse = sqs.receiveMessage(r -> r
    .queueUrl(queueUrl)
    .maxNumberOfMessages(10)  // up to 10 per call
    .waitTimeSeconds(20)       // long polling — ALWAYS use this
    .visibilityTimeout(120)    // 2 min to process
    .messageAttributeNames("All")
);

for (Message msg : receiveResponse.messages()) {
    try {
        processMessage(msg.body());
        // CRITICAL: Must delete after successful processing
        sqs.deleteMessage(r -> r
            .queueUrl(queueUrl)
            .receiptHandle(msg.receiptHandle())
        );
    } catch (Exception e) {
        // Don't delete — message will reappear after visibility timeout
        log.error("Processing failed for message: " + msg.messageId(), e);
    }
}

